import json, sys
baseline = json.load(open('baseline-packages.json'))
after = json.load(sys.stdin)
# Compare
for bp, ap in zip(baseline['projects'], after['projects']):
    for bf, af in zip(bp['frameworks'], ap['frameworks']):
        b_pkgs = {p['id']: p['resolvedVersion'] for p in bf['topLevelPackages']}
        a_pkgs = {p['id']: p['resolvedVersion'] for p in af['topLevelPackages']}
        if b_pkgs != a_pkgs:
            print(f'DIFF in {bp[\"path\"]}: {b_pkgs} vs {a_pkgs}')
print('Comparison complete: all versions match.' if all(
    {p['id']: p['resolvedVersion'] for p in bf['topLevelPackages']} == {p['id']: p['resolvedVersion'] for p in af['topLevelPackages']}
    for bp, ap in zip(baseline['projects'], after['projects'])
    for bf, af in zip(bp['frameworks'], ap['frameworks'])
) else 'DIFFERENCES FOUND')
" && dotnet package list --format json 2>/dev/null > after-cpm-packages.json

